INSERT INTO feature VALUES('session-types','sessions','Binary session types',NULL,'implemented','uncommon','mainstream languages','A channel''s protocol is a type of sends, receives, selections, offers and recursion, its endpoints used linearly. A session type stands as an argument through the type(T) quote; a receive binds its payload linearly, and a channel is delegated as a payload. A function''s parameter at a session type, written or named by a top-level type or a module''s manifest component, is an endpoint its body drives and spends, placed at the body''s entry, and a call that passes an endpoint there spends it at the caller; run, the callee acts on the caller''s channel. An endpoint at `end` is closed or dropped, `drop c` being the end action `close c` writes, and a drop of a live endpoint is refused as the session mismatch it is. An endpoint moved into a call or a closer keeps its protocol under its new name and is spent at the old one, an action after the move refused by name. A case''s arms each act on an endpoint from where the case found it, and an arm leaving it otherwise than the first is refused. A forked task exercises the authority its parent hands it and outlives no region. A session program runs on the run''s scheduler (session-machine).','core-session core-checker core-sequent runtime-emitter surface-lowering','corpus/model/sessions/seat-exchange.gandr corpus/pathological/sessions/linearity.gandr corpus/model/sessions/branched.gandr corpus/model/sessions/named-protocol.gandr corpus/model/sessions/dropped.gandr corpus/model/sessions/receive-payload.gandr corpus/model/sessions/endpoint-parameter.gandr corpus/pathological/sessions/endpoint-parameter.gandr corpus/pathological/sessions/protocol.gandr corpus/model/sessions/type-quote.gandr corpus/pathological/sessions/type-quote.gandr corpus/model/completion/buffer-moved.gandr corpus/model/completion/cancel-orders.gandr corpus/model/moves/moved-to-closer.gandr corpus/model/moves/moved-through.gandr corpus/pathological/moves/ corpus/model/tasks/authority.gandr corpus/pathological/tasks/outlived.gandr','corpus/model/sessions/seat-exchange.gandr',NULL);
